pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        vm.assume(caller != c.owner());
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            assertTrue(!success);
        } catch {
            assertTrue(true);
        }
    }
}
